import pathlib,json,html
from merge import load
out=pathlib.Path(__file__).resolve().parent
u=json.loads((out/'unit-analysis.json').read_text());d=json.loads((out/'delta.json').read_text());p=json.loads((out/'provenance.json').read_text());c=p['composition']
units={x['where']:x for r in load('/workspace/oph-build-base/latent.jsonl') for x in r.get('units',[])}
def rel(s):return 'src/'+s.split('/src/',1)[1] if '/src/' in s else s
def esc(s):return html.escape(str(s),quote=False).replace('|','\\|').replace('\r','').replace('\n','<br>')
def stop(f):return 'No lowering stop' if not f else f"{f['kind']}: {f['reason']} at {rel(f['where'])}"
def name(unit):return unit.get('name',unit['kind'])
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(esc(x) for x in row)+' |' for row in rows]])+'\n'
raw,distinct=d['raw_findings'],d['distinct_reads']
lines=['# Paired latent census: reachable and phantom overload results','','Report and evidence only. Every scratch merge completed without conflict. Only this census directory is committed; scratch merge commits and compiler changes are not pushed.','',table(['Input','Pinned commit'],[['Main tip captured at preparation',c['main']],['PathPathComponents interface adaptation',c['path']],['Step 2',c['step2']],['Step 2b (head only)',c['step2b']],['Step 3 (head only)',c['step3']],['Base scratch composition',c['base']],['Head scratch composition',c['head']]]),'The base is main plus the path adaptation and step 2. The head is that exact base plus steps 2b and 3. The four merge parents and tree IDs are retained in [composition.json](composition.json). Both sides read the single adapted tree produced by the base composition’s `apply.sh`, including a3f67b01. Both head commits and the final composed head diff touch no adaptation or meter input; see [head-adaptation-input-diff.txt](head-adaptation-input-diff.txt).','','## 1. Regressions','',table(['Regression category','Raw','Distinct'],[[label,sum(r['type']==kind for r in raw['regressions']),sum(r['type']==kind for r in distinct['regressions'])] for label,kind in [('Previously finding-free units now stopping','previously_finding_free_unit'),('New panics','new_panic'),('New refusal-scan sites','previously_finding_free_scan_site')]])]
for view,label in [(raw,'Raw'),(distinct,'Distinct')]:
 if not view['regressions']:continue
 rows=[]
 for r in view['regressions']:
  f=r.get('head') or r.get('finding');unit=r.get('unit') or units.get(f['unit']);who=name(unit) if unit else 'refusal scan';where=unit['where'] if unit else f['unit']
  rows.append([r['type'],who,rel(where),stop(f)])
 lines+=['',label+' regression entries:', '',table(['Category','Unit / scan','Unit location','Head finding and exact reason'],rows)]
if not raw['regressions'] and not distinct['regressions']:lines+=['','There are no regressions to name.']
lines+=['','All panic ledgers and every regression identity are retained in [delta.json](delta.json).','',f"Panics before/after: {len(raw['panics']['before'])}/{len(raw['panics']['after'])} raw; {len(distinct['panics']['before'])}/{len(distinct['panics']['after'])} distinct.",'','## 2. Cleared, moved and new findings','',table(['Measure','Raw','Distinct outermost accesses'],[[label,len(raw[field]),len(distinct[field])] for label,field in [('Cleared: no finding remains at identity','lowered'),('Moved: old reason gone, another remains','moved'),('New findings','new_findings'),('New sites','new_sites'),('Changed unit first stops','unit_first_stop_delta'),('Regressions','regressions')]]),'Raw identities retain kind, source identity, reason and text. Distinct identities use the unmodified base composition’s `stage3/census/pair` tool: source path, source SHA-256, outermost contiguous property/element access start and exact reason. Newly exposed reasons in already-blocked units are not automatically regressions. [pair-report.md](pair-report.md) and [delta.json](delta.json) retain both complete views.','',table(['Finding kind','Base raw','Head raw','Base distinct','Head distinct'],[[kind,raw['totals']['before'].get(kind,0),raw['totals']['after'].get(kind,0),distinct['totals']['before'].get(kind,0),distinct['totals']['after'].get(kind,0)] for kind in sorted(set(raw['totals']['before'])|set(raw['totals']['after']))])]
for title,field,member in [('Cleared raw identities','lowered','base'),('New raw findings','new_findings','finding')]:
 lines+=['',title+':','',table(['Location','Kind','Exact reason'],[[rel(r[member]['where']),r[member]['kind'],r[member]['reason']] for r in raw[field]])]
lines+=['','## 3. getPathComponents: all 11 units','','“Newly admitted” follows the requested criterion: the unit stopped at base and, on head, either has no first stop or first-stops on something other than an overload-result refusal. It does not claim that an already-blocked unit compiles. Locations are one-based lines and UTF-16 columns.','']
def cohort_table(rows,invariant=False):
 headers=['Unit','Unit location','Base first stop','Head first / next stop','Newly admitted']+(['Head invariant-mutable'] if invariant else [])
 return table(headers,[[name(r['unit']),rel(r['unit']['where']),stop(r['base']),stop(r['head']),'yes' if r['newly_admitted'] else 'no']+(['yes' if r['head_invariant_mutable'] else 'no'] if invariant else []) for r in rows])
def admitted(rows):return '; '.join(name(r['unit'])+' (`'+rel(r['unit']['where'])+'`)' for r in rows if r['newly_admitted']) or 'None.'
path=u['getPathComponents'];supported=u['getSupportedExtensions']
lines +=[cohort_table(path),f"**{sum(r['newly_admitted'] for r in path)}/11 newly admitted.** Exact next-stop reason words are in the table above.",'','Every newly admitted unit: '+admitted(path), '','The adapted PathPathComponents interface and its source hash are retained in [path-components-interface.json](path-components-interface.json).','','## 4. getSupportedExtensions: all 5 units','',cohort_table(supported,True),f"**{sum(r['newly_admitted'] for r in supported)}/5 newly admitted** by the same criterion. Exact next-stop reason words are in the head column.",'','Every newly admitted unit: '+admitted(supported),'',f"`adamic/invariant-mutable` appears in **{sum(r['head_invariant_mutable'] for r in supported)}/5 head first/next-stop diagnostics**. The table preserves each finding’s exact `reason`; the rule code is detected in its full diagnostic `text`, including its fix, and is not added to the reason words.",'','## 5. Overload-result first-stop counts','',table(['Measure','Base composition','Head composition'],[['Overload-result first stops',u['overload_result_base'],u['overload_result_head']],['Resolved source files',len(u['header']['sources']),len(u['header']['sources'])],['Checker diagnostics',0,0],['Units',u['units'],u['units']],['Attempted units',u['attempted_base'],u['attempted_head']],['Attempted units with no first stop',u['no_stop_base'],u['no_stop_head']]]),'','## Method and validation','','The workflow reuses the tools and first-error latent mode from `stage3/census/overload-proof-3a7ea290` (commit 353218cbd01286116bd97fc1475b51bc54cdce75). No earlier measurement stream is reused. Both overlays are built from their own composed source trees, using their own `make_overlay.py` and `entry_overlay.py`, and exact recursive submodule pins. Both read the same base-produced adapted bytes, pinned to TypeScript 6.0.3 `050880ce59e30b356b686bd3144efe24f875ebc8`. Source hashes, overlay maps and executable hashes are in the evidence.','','`LATENT_FULL=0` and `LATENT_ASSERT_NO_OUTPUT=1`. Ordinary Load and Lower remain disabled; no backend or usable IR is produced. Per-unit eligibility, findings and timing records are retained. A unit without a finding is not proof of whole-program compilation.','','Each side runs eight disjoint attempted-unit shards over the complete project, with two shards per side concurrent and `GOMEMLIMIT=3GiB`. Selection is after unchanged checker-body eligibility and generic deferral, before an independent attempt. Dependencies and registration are not filtered. Shards 0 and 1 retain complete refusal scans and must agree exactly; shards 2–7 omit only repeated scans. Deferred/skipped unit records deduplicate, and generic call witnesses union under the original Go ordering and five-witness cap. Each attempted unit must occur exactly once. Process-scoped relation/cache reports remain separate, never summed; any overflow or global finding stops composition.','','Both binary variants on both sides pass the unsharded-versus-sharded composition fixture, including a real overloaded-value first stop and cross-shard generic witnesses. Both existing latent audits and all 20 pairing tests pass. The bounded fixture validates the splitting mechanism; no full unsharded census is claimed. A stock-parser inventory independently checks every top-level unit and its source order. Final validation checks shard membership, exact archived-stream recomposition, all per-unit timings, source hashes and both requested cohort sizes.','','Every timing wrapper reports its child’s own exit code and exits with it; signal exits use shell encoding. Every shell wrapper also reports and propagates its child’s status. Each child is bounded at 1,740 seconds with at most ten seconds to kill, below 30 minutes. No measured child timed out. All Go evidence is named `.go.txt`; raw JSONL and logs are gzip compressed without changing their bytes. `commands.md`, the retained scripts, provenance, merge logs, per-side raw streams and `validation.json` make the measurement reviewable.','']
stats=[]
for side in ['base','head']:
 for i in range(8):
  x=json.loads((out/side/f'shard-{i}.time.json').read_text());assert x['exit_code']==0 and not x['timed_out'] and x['wall_seconds']<1800
  stats.append([side,i,round(x['wall_seconds'],3),round(x['user_seconds'],3),round(x['system_seconds'],3),round(x['peak_rss_kib']/1024,2),x['exit_code']])
lines+=['Each census child’s own measurements (overlapping runs):','',table(['Side','Shard','Wall s','User s','System s','Peak RSS MiB','Child exit'],stats)]
(out/'REPORT.md').write_text('\n'.join(lines).rstrip()+'\n');print('report written; newly admitted path',sum(r['newly_admitted'] for r in path),'supported',sum(r['newly_admitted'] for r in supported),'regressions',len(raw['regressions']))
